SELECT count(*) FROM deals_enriched WHERE deal_date BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND product_base IN ('рис','рис шлифованный','рис шлифованный 1 сорт','рис шлифованный высший сорт');
SELECT CASE WHEN unit='килограмм' THEN 'тонна' ELSE unit END AS u, round(sum(CASE WHEN unit='килограмм' THEN volume_units/1000 ELSE volume_units END),2), count(*), round(sum(amount_uzs)) FROM deals_enriched WHERE deal_date BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND product_base IN ('рис','рис шлифованный','рис шлифованный 1 сорт','рис шлифованный высший сорт') AND status<>'Аннулирован(Не оплачен)' GROUP BY 1 ORDER BY 3 DESC;
SELECT product_base AS g, NULL AS k, NULL AS u, count(*) FROM deals_enriched d  WHERE deal_date BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND product_base IN ('рис','рис шлифованный','рис шлифованный 1 сорт','рис шлифованный высший сорт') GROUP BY 1, 2, 3 ORDER BY 4 DESC NULLS LAST LIMIT 8
